import forge.ai.*;
import forge.ai.bridge.*;
import forge.deck.Deck;
import forge.game.*;
import forge.game.card.*;
import forge.game.player.*;
import forge.game.phase.*;
import forge.game.zone.*;
import com.google.gson.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;

/** Partial spending, multiple sources, persistence and actual phase-end clearing. */
public class FloatingManaReplayRegression extends AITest {
 static JsonObject activate(Card card){JsonObject r=new JsonObject();r.addProperty("op","activate_basic");r.addProperty("card_id",card.getId());r.addProperty("card_name",card.getName());JsonObject params=new JsonObject();card.getManaAbilities().get(0).getMapParams().forEach(params::addProperty);r.add("parameters",params);return r;}
 static JsonObject unit(Card card,String color){JsonObject m=new JsonObject();m.addProperty("source_card_id",card.getId());m.addProperty("color",color);m.addProperty("snow",false);m.addProperty("restricted",false);return m;}
 static JsonObject spend(Card card,String color){JsonObject r=new JsonObject();r.addProperty("op","spend");r.add("mana",unit(card,color));return r;}
 public static void main(String[] args)throws Exception {
  boolean multiple=args[0].equals("multiple");Path root=Path.of(args[1]);Files.createDirectories(root);System.setProperty("forge.audit.directory",root.resolve("audit").toString());FloatingManaReplayRegression test=new FloatingManaReplayRegression();test.initializeModel();test.initAndCreateGame();
  List<RegisteredPlayer> seats=new ArrayList<>();for(int i=0;i<4;i++)seats.add(new RegisteredPlayer(new Deck()).setPlayer(new LobbyPlayerAi("seat"+i,null)));GameRules rules=new GameRules(GameType.Constructed);Game game=new Game(seats,rules,new Match(rules,seats,"Floating mana"));Player p=game.getPlayers().get(0);for(Player x:game.getPlayers())test.fillLibrary(x,10);
  game.setAge(GameStage.Play);game.getPhaseHandler().devModeSet(PhaseType.MAIN1,p,false);game.getPhaseHandler().setPriority(p);Card ring=test.addCardToZone("Sol Ring",p,ZoneType.Battlefield);Card island=test.addCardToZone("Island",p,ZoneType.Battlefield);Card card=test.addCardToZone(multiple?"Mind Stone":"Skullclamp",p,ZoneType.Hand);var spell=card.getFirstSpellAbility();spell.setActivatingPlayer(p);
  JsonObject row=new JsonObject();row.addProperty("kind","decision");row.addProperty("index",0);row.addProperty("actor_id",p.getId());row.addProperty("hook","forge/game/player/PlayerController.payManaCost(Lforge/game/cost/CostPartMana;Lforge/game/spellability/SpellAbility;Ljava/lang/String;Lforge/game/mana/ManaConversionMatrix;Z)Z");row.addProperty("decision_type","fixed_tap_mana");row.addProperty("component",multiple?"{2}":"{1}");row.addProperty("source_ability",card.getId()+":"+spell.getId());row.addProperty("ability_api","PermanentNoncreature");JsonArray ops=new JsonArray();ops.add(activate(ring));ops.add(spend(ring,"C"));if(multiple){ops.add(activate(island));ops.add(spend(island,"U"));}row.add("operations",ops);
  JsonObject pass=new JsonObject();pass.addProperty("kind","decision");pass.addProperty("index",1);pass.addProperty("actor_id",p.getId());pass.addProperty("hook",p.getController().getClass().getName().replace('.','/')+".chooseSpellAbilityToPlay()Ljava/util/List;");pass.addProperty("decision_type","priority_pass");pass.addProperty("pass_return","null");pass.addProperty("empty_mana_pool",false);JsonArray pool=new JsonArray();pool.add(unit(ring,"C"));pass.add("expected_pool",pool);JsonObject context=new JsonObject();context.addProperty("turn",game.getPhaseHandler().getTurn());context.addProperty("phase","MAIN1");context.addProperty("priority_player_id",p.getId());context.addProperty("turn_player_id",p.getId());pass.add("context",context);
  JsonObject rejectedAttempt=spend(ring,"C");rejectedAttempt.addProperty("expected_success",false);ops.add(rejectedAttempt);
  Path tape=root.resolve("decisions.jsonl");Files.writeString(tape,row+"\n"+pass+"\n{\"kind\":\"decision_tape_complete\",\"decisions\":2}\n",StandardOpenOption.CREATE_NEW);System.setProperty("forge.decision.replayTape",tape.toString());System.setProperty("forge.decision.replaySha256",HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(tape))));System.setProperty("forge.decision.replayDiagnostics",root.resolve("diagnostics").toString());DurableEvidence.begin("floating-fixture");EngineEvidence.begin(game);
  if(!ComputerUtil.handlePlayingSpellAbility(p,spell,null))throw new AssertionError("Actual cast failed");var stacked=game.getStack().peekAbility();if(stacked.getPayingMana().size()!=(multiple?2:1)||p.getManaPool().totalMana()!=1||!ring.isTapped()||island.isTapped()!=multiple)throw new AssertionError("Partial spend or source chain differs");
  if(p.getController().chooseSpellAbilityToPlay()!=null||p.getManaPool().totalMana()!=1)throw new AssertionError("Passing priority lost floating mana");game.getStack().resolveStack();if(p.getManaPool().totalMana()!=1||p.getCardsIn(ZoneType.Battlefield).stream().noneMatch(c->c.getName().equals(card.getName())))throw new AssertionError("Resolution lost unspent mana or permanent");
  var end=PhaseHandler.class.getDeclaredMethod("onPhaseEnd");end.setAccessible(true);end.invoke(game.getPhaseHandler());if(!p.getManaPool().isEmpty())throw new AssertionError("Actual phase-end handler failed to clear mana");DecisionReplay.finish();EngineEvidence.finish();JsonObject result=new JsonObject();result.addProperty("seed",96);result.addProperty("status","completed");DurableEvidence.finish(root.resolve("results"),96,"fixture\nDragonMind Result: "+result+"\n",result);
  int announcements=0,produced=0,spent=0,cleared=0;for(String line:Files.readAllLines(root.resolve("audit/referee-events.jsonl"))){JsonObject e=JsonParser.parseString(line).getAsJsonObject();String hook=e.has("hook")?e.get("hook").getAsString():"";if(e.has("public_payload")){if(e.getAsJsonArray("entitled_player_ids").size()!=4||!e.getAsJsonObject("public_payload").getAsJsonObject("counts").get("C").getAsString().equals("1"))throw new AssertionError("Public pool entitlement/counts differ");announcements++;}if(e.get("kind").getAsString().equals("engine_call")&&hook.contains("ManaPool.addMana("))produced++;if(e.get("kind").getAsString().equals("engine_return")&&hook.contains("ManaPool.tryPayCostWithMana(")&&e.get("result").getAsBoolean())spent++;if(e.get("kind").getAsString().equals("engine_return")&&hook.contains("ManaPool.clearPool(")&&e.getAsJsonArray("mana_pool_after").isEmpty())cleared++;}
  if(announcements!=2||produced!=(multiple?2:1)||spent!=(multiple?2:1)||cleared<1)throw new AssertionError("Production/payment/announcement/clearing evidence missing");System.out.println("PASS four-player "+args[0]+": recorded production/spending;1C persists across pass and resolution;phase-end clears;public evidence independently recorded");System.exit(0);
 }
}
